  TelePremiumNetworkLibrary.addIptvFile("Local file","content://selected/m3u","#EXTM3U\n#EXTINF:-1,TV\nhttps://tv.test/stream\n");TelePremiumMediaLibrarySync.start();reset(false);TelePremiumMediaLibrarySync.start();check(TelePremiumNetworkLibrary.inlinePlaylist("content://selected/m3u").contains("https://tv.test/stream"),"imported playlist contents restore without the old phone's document grant");
