def run():
 with tempfile.TemporaryDirectory(prefix='tp-media-settings-') as directory:
  base=Path(directory);src=base/'src';out=base/'classes';src.mkdir();out.mkdir()
  for name,content in FILES.items():p=src/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
  names=['xray/XrayProfile','xray/XrayConfig','xray/XrayProfileStore','cloud/CloudNode','cloud/CloudSnapshot','cloud/CloudConflictResolver','cloud/TelePremiumCloudResetState','media/TelePremiumMediaItem','media/TelePremiumMediaLibraryStore','media/TelePremiumMediaLibrarySync','media/TelePremiumMediaPreferences','media/TelePremiumNetworkLibrary','media/TelePremiumPlaylistRepository','media/TelePremiumAudioEffects','media/TelePremiumQueueManager']
  compiler=['javac'] if shutil.which('javac') else ['java','com.sun.tools.javac.Main']
  sources=sorted(src.rglob('*.java'))+sorted((ROOT/'scripts/tests/stubs').rglob('*.java'))+[PROD/('org/telegram/messenger/telepremium/'+name+'.java') for name in names]
  subprocess.run([*compiler,'-d',str(out),*map(str,sources)],check=True);subprocess.run(['java','-cp',str(out),'MediaSettingsSyncRuntimeTest'],check=True)
if __name__=='__main__':run()
